    lines: [{ qty: 5, unitPrice: 5000, discountPercent: 100, vatRate: 21 }],
  };
  const result = invoiceTotals(invoice);

  assert.equal(result.subtotal, 25000);
  assert.equal(result.discount, 25000);
  assert.equal(result.vat, 0);
  assert.equal(result.total, 0);
});

test('invoiceTotals with decimal discount percentage', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 5000, discountPercent: 12.5, vatRate: 21 }],
  };
  const result = invoiceTotals(invoice);

  assert.equal(result.subtotal, 25000);
  assert.equal(result.discount, 3125);
});

test('invoiceTotals includes voucher field', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 5000, discountPercent: 0, vatRate: 21 }],
  };
  const result = invoiceTotals(invoice);

  assert.equal(result.voucher, 0);
});

test('invoiceTotals with voucher calculates total correctly', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 5000, discountPercent: 0, vatRate: 21 }],
    voucher: { code: 'TEST', amount: 5000 },
  };
  const result = invoiceTotals(invoice);

  assert.equal(result.total, 25250); // 30250 - 5000
});

test('invoiceTotals with voucher larger than final total clamps to 0', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 5000, discountPercent: 0, vatRate: 21 }],
    voucher: { code: 'TEST', amount: 1000000 },
  };
  const result = invoiceTotals(invoice);

  assert.equal(result.total, 0);
});

test('invoiceTotals does not mutate the invoice', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 5000, discountPercent: 0, vatRate: 21 }],
  };
  const original = JSON.stringify(invoice);

  invoiceTotals(invoice);

  assert.equal(JSON.stringify(invoice), original);
});

test('invoiceTotals total formula: subtotal - discount + vat - voucher', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 5000, discountPercent: 10, vatRate: 21 },
      { qty: 5, unitPrice: 5000, discountPercent: 5, vatRate: 9 },
    ],
    voucher: { code: 'TEST', amount: 2000 },
  };
  const result = invoiceTotals(invoice);

  const expected = result.subtotal - result.discount + result.vat - result.voucher;
  assert.equal(result.total, expected);
});

test('invoiceTotals with multiple VAT rates', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 5000, discountPercent: 0, vatRate: 21 },
      { qty: 5, unitPrice: 2000, discountPercent: 0, vatRate: 9 },
      { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 0 },
    ],
  };
  const result = invoiceTotals(invoice);

  assert.equal(result.subtotal, 60000);
  assert.ok(result.vat > 0);
});

test('invoiceTotals clamping returns non-negative totals', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 5000, discountPercent: 0, vatRate: 21 }],
  };
  const result = invoiceTotals(invoice);

  assert.ok(result.subtotal >= 0);
  assert.ok(result.discount >= 0);
  assert.ok(result.vat >= 0);
  assert.ok(result.voucher >= 0);
  assert.ok(result.total >= 0);
});

test('lineVAT with undefined discount percent defaults to 0', () => {
  const line = { qty: 100, unitPrice: 5000, vatRate: 21 };
  // qty >= 10 so bulk discount applies: 500000 * 0.025 = 12500
  // Amount after all discounts: 500000 - 12500 = 487500
  // VAT: 487500 * 0.21 = 102375
  const result = lineVAT(line);

  assert.equal(result, 102375);
});

test('invoiceTotals with undefined discount percent on line', () => {
  const invoice = {
    lines: [{ qty: 100, unitPrice: 5000, vatRate: 21 }],
  };
  const result = invoiceTotals(invoice);

  // qty >= 10 so bulk discount applies
  assert.equal(result.discount, 12500);
  assert.equal(result.total, 500000 - 12500 + 102375);
});

test('lineTotal with decimal values', () => {
  const line = { qty: 1, unitPrice: 1.5, discountPercent: 0, vatRate: 21 };
  assert.equal(lineTotal(line), 1.5);
});

test('invoiceTotals preserves fields in correct order', () => {
  const invoice = {
    lines: [{ qty: 100, unitPrice: 5000, discountPercent: 0, vatRate: 21 }],
  };
  const result = invoiceTotals(invoice);
  const keys = Object.keys(result);

  assert.deepEqual(keys, ['subtotal', 'discount', 'vat', 'voucher', 'total']);
});

test('lineVAT with bulk discount (qty >= 10)', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 21 };
  // Total: 10000, Line discount: 0, After line discount: 10000
  // Bulk discount (2.5%): 250
  // After bulk discount: 9750
  // VAT: 9750 * 21 / 100 = 2047.5 ≈ 2048
  const result = lineVAT(line);
  assert.equal(result, 2048);
});

test('lineVAT with bulk discount and line discount', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: 10, vatRate: 21 };
  // Total: 10000, Line discount: 1000, After line discount: 9000
  // Bulk discount (2.5%): 225
  // After bulk discount: 8775
  // VAT: 8775 * 21 / 100 = 1842.75 ≈ 1843
  const result = lineVAT(line);
  assert.equal(result, 1843);
});

test('lineVAT without bulk discount (qty < 10)', () => {
  const line = { qty: 9, unitPrice: 1000, discountPercent: 0, vatRate: 21 };
  // Total: 9000, Line discount: 0, After line discount: 9000
  // No bulk discount (qty < 10)
  // VAT: 9000 * 21 / 100 = 1890
  const result = lineVAT(line);
  assert.equal(result, 1890);
});

test('invoiceTotals includes bulk discount in discount total', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 21 }],
  };
  const result = invoiceTotals(invoice);

  // Subtotal: 10000, Line discount: 0, Bulk discount: 250
  assert.equal(result.subtotal, 10000);
  assert.equal(result.discount, 250);
  assert.equal(result.total, 9750 + 2048);
});

test('invoiceTotals with line discount and bulk discount', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, discountPercent: 10, vatRate: 21 }],
  };
  const result = invoiceTotals(invoice);

  // Subtotal: 10000
  // Line discount: 1000
  // After line discount: 9000
  // Bulk discount: 225
  // Total discount: 1225
  assert.equal(result.subtotal, 10000);
  assert.equal(result.discount, 1225);
});

test('invoiceTotals bulk discount only applies to qty >= 10', () => {
  const invoice = {
    lines: [{ qty: 9, unitPrice: 1000, discountPercent: 0, vatRate: 21 }],
  };
  const result = invoiceTotals(invoice);

  // No bulk discount since qty < 10
  assert.equal(result.discount, 0);
});

test('invoiceTotals with multiple lines, some with bulk discount', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 21 },
      { qty: 5, unitPrice: 1000, discountPercent: 0, vatRate: 21 },
    ],
  };
  const result = invoiceTotals(invoice);

  // Line 1: Total 10000, Bulk discount 250
  // Line 2: Total 5000, No bulk discount
  assert.equal(result.subtotal, 15000);
  assert.equal(result.discount, 250);
});

test('lineVAT bulk discount with 0% VAT rate', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 0 };
  // Bulk discount applies, but VAT is 0%
  const result = lineVAT(line);
  assert.equal(result, 0);
});

test('invoiceTotals bulk discount exact boundary (qty = 10)', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 21 }],
  };
  const result = invoiceTotals(invoice);

  // Bulk discount should apply at qty = 10
  assert.ok(result.discount > 0);
});

test('invoiceTotals bulk discount does not apply at boundary (qty = 9)', () => {
